import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { toJob, validateSubmission, type FieldError, type JobRow, type Submission } from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** The worker is "up" if its heartbeat is at most this old. */
const WORKER_STALE_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'No such resource.');
}

function methodNotAllowed(res: ServerResponse, allow: string[]): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this resource.', undefined);
  res.setHeader('allow', allow.join(', '));
}

function mediaType(header: string | undefined): string | undefined {
  return header?.split(';')[0]?.trim().toLowerCase();
}

/** Reads the request body, up to MAX_BODY_BYTES. Oversized bodies are drained but flagged. */
function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function getRowById(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

function getRowByKey(key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  let idempotencyKey: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY.test(keyHeader)) idempotencyKey = keyHeader;
    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let submission: Submission | undefined;
  if (mediaType(req.headers['content-type']) !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    errors.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let parsedOk = true;
    try {
      parsed = JSON.parse(text);
    } catch {
      parsedOk = false;
      errors.push({ field: 'body', message: 'body is not valid JSON' });
    }
    if (parsedOk) {
      const result = validateSubmission(parsed);
      if (result.ok) submission = result.value;
      else errors.push(...result.fields);
    }
  }

  if (errors.length > 0 || !submission) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', errors);
    return;
  }

  // Check-and-insert runs in one immediate transaction, so the same key cannot create two jobs,
