import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import type { JobRow } from './jobs.ts';

const STEP_MS = 100;
const MAX_ATTEMPTS = 3;
const RETRY_MIN_MS = 250;
const RETRY_MAX_MS = 2000;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  db.prepare(
    "INSERT INTO heartbeats (name, at_ms) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms",
  ).run(Date.now());
}

function nextQueuedJob(): JobRow | undefined {
  return db
    .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after_ms <= ? ORDER BY seq LIMIT 1")
    .get(Date.now()) as unknown as JobRow | undefined;
}

function setRunning(seq: number, attempt: number): void {
  db.prepare("UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at_ms = ? WHERE seq = ?").run(
    attempt,
    Date.now(),
    seq,
  );
}

function setProgress(seq: number, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at_ms = ? WHERE seq = ?').run(completed, Date.now(), seq);
}

function requeue(seq: number, runAfterMs: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_after_ms = ?, updated_at_ms = ? WHERE seq = ?").run(
    runAfterMs,
    Date.now(),
    seq,
  );
}

function complete(seq: number, steps: number, output: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', progress_completed = ?, output = ?, error = NULL, updated_at_ms = ? WHERE seq = ?",
  ).run(steps, output, Date.now(), seq);
}

function fail(seq: number, error: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', error = ?, output = NULL, updated_at_ms = ? WHERE seq = ?").run(
    error,
    Date.now(),
    seq,
  );
}

function retryDelayMs(): number {
  return RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS + 1));
}

/** Runs one attempt of a job. The attempt number is the job's attempts count plus one. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts + 1;
  setRunning(job.seq, attempt);

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) fail(job.seq, 'transient failure');
    else requeue(job.seq, Date.now() + retryDelayMs());
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Graceful shutdown: hand the job back so the next worker start picks it up at once.
      requeue(job.seq, 0);
      return;
    }
    setProgress(job.seq, step);
  }
  complete(job.seq, job.steps, job.input.toUpperCase());
}

// A job left in 'running' means a previous worker died mid-attempt. Process it again.
db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at_ms = ? WHERE status = 'running'").run(Date.now());

heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  const job = nextQueuedJob();
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeatTimer);
